const P={};T.split("\n").forEach(l=>{const[id,n,w,am,van,th,cat,d,t,h,nh,ss]=l.split("|");P[id]={id,n,w,am,van,th,cat,d,t,h,nh,ss,svg:S[id]}});
const img=(id,x,y,s)=>`<svg x="${x}" y="${y}" width="${s}" height="${s}" viewBox="0 0 100 100">${S[id]||""}</svg>`;
const esc=s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const tx=(x,y,t,sz=14,a="middle",c=IN,w=800)=>`<text x="${x}" y="${y}" text-anchor="${a}" font-size="${sz}" font-weight="${w}" font-family="Nunito,sans-serif" fill="${c}">${esc(t)}</text>`;
const gridOf=(id,n,x0,y0,cols,s,cross=0,fade=0)=>{let o="";for(let i=0;i<n;i++){const x=x0+(i%cols)*s,y=y0+Math.floor(i/cols)*s;o+=`<g${i<fade?' opacity=".25"':""}>${img(id,x,y,s-4)}</g>`;if(i>=n-cross)o+=`<path d="M${x+6} ${y+6}L${x+s-10} ${y+s-10}M${x+s-10} ${y+6}L${x+6} ${y+s-10}" stroke="#e0473a" stroke-width="5" stroke-linecap="round"/>`}return o};
