 two:p=>{const c1=Math.min(p.n1,4),c2=Math.min(p.n2,4),h=Math.max(Math.ceil(p.n1/c1),Math.ceil(p.n2/c2))*44+26;return`<svg viewBox="0 0 ${c1*44+c2*44+40} ${h}">${gridOf(p.id1,p.n1,0,0,c1,44)}<path d="M${c1*44+20} 0V${h-22}" stroke="#adb5bd" stroke-width="3" stroke-dasharray="6 5"/>${gridOf(p.id2,p.n2,c1*44+40,0,c2,44)}${tx(c1*22,h-4,p.l1||"Bên trái",13)}${tx(c1*44+40+c2*22,h-4,p.l2||"Bên phải",13)}</svg>`},
 groups:p=>{const per=p.box?Math.min(p.n,5):Math.min(p.n,4),rows=Math.ceil(p.n/per),s=26,bw=per*s+16,bh=rows*s+16,cols=Math.min(p.g,4),gr=Math.ceil(p.g/cols),left=p.left||0;let o="";for(let i=0;i<p.g;i++){const x=(i%cols)*(bw+12),y=Math.floor(i/cols)*(bh+12);o+=`<rect x="${x}" y="${y}" width="${bw}" height="${bh}" rx="${p.box?6:bh/2}" fill="${p.box?"#fff3bf":"#e7f5ff"}" stroke="${p.box?"#f5b301":"#74c0fc"}" stroke-width="2.5"/>`+gridOf(p.id,p.n,x+8,y+8,per,s)}
  const W=cols*(bw+12)+(left?3*26+10:0),H=Math.max(gr*(bh+12),left?Math.ceil(left/3)*26+16:0);if(left)o+=gridOf(p.id,left,cols*(bw+12)+6,8,3,26);return`<svg viewBox="0 0 ${W} ${H}">${o}</svg>`},
